function otCredencialBasicaGuardar() {
  if (!otPuedeEditarCredenciales() || !_otCredencialesClienteActual || !window.fbDB) {
    notify('No se puede guardar esta credencial');
    return;
  }
  var titulo = String((document.getElementById('ot-cred-titulo') || {}).value || '').trim();
  var usuario = String((document.getElementById('ot-cred-usuario') || {}).value || '').trim();
  var password = String((document.getElementById('ot-cred-password') || {}).value || '').trim();
  var serie = String((document.getElementById('ot-cred-serie') || {}).value || '').trim();
  if (!titulo) { notify('Ingresá un título para identificar la credencial'); return; }
  if (!usuario && !password && !serie) { notify('Ingresá usuario, contraseña o número de serie'); return; }
  var clienteKey = String(_otCredencialesClienteActual.fbKey || _otCredencialesClienteActual.id || '');
  if (!clienteKey) { notify('El cliente no tiene un identificador válido'); return; }
  var btn = document.getElementById('ot-cred-guardar-btn');
  if (btn) btn.disabled = true;
  var datos = {
    tipo: 'otro', desc: titulo, user: usuario, pass: password, serie: serie,
    ts: Date.now(), editadoPor: currentUser || ''
  };
  return window.fbPush(window.fbRef(window.fbDB, 'sisventas/credencialesPorCliente/' + clienteKey), datos)
    .then(function() {
      notify('✓ Credencial guardada para ' + (_otCredencialesClienteActual.nombre || _otCredencialesClienteActual.empresa || 'el cliente'));
      otCredencialBasicaCerrar();
      var ot = (otData || []).find(function(item) {
        return item.fbKey === otActualId || item.id === otActualId;
      }) || _otCredencialesOTActual;
      if (ot) otCargarCredenciales(ot);
    })
    .catch(function(error) { notify('Error al guardar: ' + error.message); })
    .finally(function() { if (btn) btn.disabled = false; });
}

function toggleChecklistFase(fase) {
  var ot = otData.find(function(o){ return o.id === otActualId || o.fbKey === otActualId; });
  if (!ot || !CHECKLISTS[fase]) return;
  if (otEstaCerrada(ot)) {
    notify('La OT ya está finalizada y su checklist no puede modificarse.');
    return;
  }
  var claveGuardado = String(ot.fbKey || ot.id || otActualId) + ':' + fase;
  if (_otChecklistGuardando[claveGuardado]) {
    notify('Esperá a que termine de guardarse esta etapa.');
    return;
  }
  normalizarChecklistOT(ot);
  var estadoAnterior = ot.checks[fase].slice();
  var auditAnteriorLength = Array.isArray(ot.audit) ? ot.audit.length : 0;
  var marcar = !ot.checks[fase].every(Boolean);
  ot.checks[fase] = CHECKLISTS[fase].map(function(){ return marcar; });
  var ahora = new Date().toLocaleDateString('es-AR') + ' ' + new Date().toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'});
  if (!ot.audit) ot.audit = [];
  var nombresFase = { preparacion:'Preparación', instalacion:'Instalación', verificacion:'Verificación y entrega' };
  ot.audit.push({
    fecha: ahora,
    usuario: currentUser || (currentRole === 'admin' ? 'Admin' : ot.tecnico),
    accion: (marcar ? '✓ Completó toda la etapa: ' : '✗ Desmarcó toda la etapa: ') + nombresFase[fase]
  });
  actualizarProgreso(ot);
  renderChecklist('checklist-' + fase, ot.checks[fase], CHECKLISTS[fase], otActualId, fase);
  if (typeof fbGuardarOT === 'function') {
    _otChecklistGuardando[claveGuardado] = true;
    return fbGuardarOT(ot)
      .catch(function(e){
        ot.checks[fase] = estadoAnterior;
        if (Array.isArray(ot.audit)) ot.audit.length = auditAnteriorLength;
        actualizarProgreso(ot);
        renderChecklist('checklist-' + fase, ot.checks[fase], CHECKLISTS[fase], otActualId, fase);
        notify('No se pudo guardar esta etapa: ' + e.message);
      })
      .finally(function(){ delete _otChecklistGuardando[claveGuardado]; });
  } else {
    ot.checks[fase] = estadoAnterior;
    if (Array.isArray(ot.audit)) ot.audit.length = auditAnteriorLength;
    actualizarProgreso(ot);
    renderChecklist('checklist-' + fase, ot.checks[fase], CHECKLISTS[fase], otActualId, fase);
    notify('No se pudo guardar esta etapa: Firebase no está disponible');
  }
}

function firmaLimpiar(soloVisual) {
  var canvas = document.getElementById('firma-canvas');
  if (!canvas) return;
  if (_firmaCtx) {
    _firmaCtx.clearRect(0, 0, canvas.width / window.devicePixelRatio, canvas.height / window.devicePixelRatio);
  }
  canvas.style.backgroundImage = 'none';
  firmaAplicarBloqueo('cliente', false);
  if (_firmaGuardadoTimer) clearTimeout(_firmaGuardadoTimer);
  _firmaGuardadoTimer = null;
  _firmaGuardadoPendiente = false;
  _firmaTiene = false;
  document.getElementById('firma-placeholder').style.display = '';
  document.getElementById('firma-guardada-badge').style.display = 'none';
  if (soloVisual === true) return;
  var ot = (otData||[]).find(function(o){ return o.fbKey === otActualId || o.id === otActualId; });
  if (!ot || !ot.fbKey || !window.fbDB) return;
  var firmaAnterior = otFirmaUrl(ot);
  var pathAnterior = ot.firmaStoragePath || '';
  window._otGuardandoLocalHasta = Date.now() + 2500;
  return otPersistirActualizar(ot.fbKey, {
    firmaClienteUrl: null,
    firmaUrl: null,
    firmaURL: null,
    firmaBase64: null,
    firmaCliente: null,
    firma: null,
    firmaStoragePath: null,
    firmada: false,
    fechaFirma: null,
    conformidadCliente: null
  }).then(function() {
    ot.firmaClienteUrl = null;
    ot.firmaUrl = null;
    ot.firmaURL = null;
    ot.firmaBase64 = null;
    ot.firmaCliente = null;
    ot.firma = null;
    ot.firmaStoragePath = null;
    ot.firmada = false;
    ot.fechaFirma = null;
    ot.conformidadCliente = '';
    var conformidadSelect = document.getElementById('ot-acta-conf');
    if (conformidadSelect) conformidadSelect.value = '';
    window._otDetalleHuella = otHuellaDetalle(ot);
    if (pathAnterior && window.fbDeleteObject && window.fbStorageRef && window.fbStorage) {
      window.fbDeleteObject(window.fbStorageRef(window.fbStorage, pathAnterior)).catch(function(error) {
        console.warn('La firma se quitó de la OT, pero no se pudo limpiar su archivo:', error);
      });
    }
    notify('✓ Firma eliminada');
    if (typeof actualizarPanelIntegridadOT === 'function') actualizarPanelIntegridadOT();
  }).catch(function(error) {
    ot.firmaClienteUrl = firmaAnterior;
    ot.firmaStoragePath = pathAnterior;
    firmaCargar(ot);
    notify('No se pudo eliminar la firma: ' + error.message);
  });
}

