function guardarLogoEmpresa() {
  if (!_logoFileEmpresa && !_logoCropOriginal) return;
  var status = document.getElementById('cfg-logo-status');
  if (status) status.textContent = 'Guardando...';
  try {
    var base64 = renderLogoCropToDataUrl(0.92) || _logoCropOriginal;
    window.logoEmpresaUrl = base64;

    var onOk = function() {
      if (status) status.textContent = 'Logo guardado ✓';
      var saveBtn = document.getElementById('cfg-logo-save-btn');
      var delBtn  = document.getElementById('cfg-logo-delete-btn');
      var img     = document.getElementById('cfg-logo-img');
      if (saveBtn) saveBtn.style.display = 'none';
      if (delBtn)  delBtn.style.display  = '';
      if (img)     img.style.opacity     = '1';
      var cropper = document.getElementById('cfg-logo-cropper');
      if (cropper) cropper.style.display = 'none';
      _logoFileEmpresa = null;
      _logoCropOriginal = '';
      aplicarLogo(base64);
      notify('Logo guardado ✓');
    };

    if (window.fbDB && window.fbSet && window.fbRef) {
      return window.fbSet(window.fbRef(window.fbDB, 'sisventas/config/logoUrl'), base64)
        .then(onOk)
        .catch(function(err) {
          // Fallback localStorage
          try { localStorage.setItem('nixa_logo', base64); } catch(ex) {}
          if (status) status.textContent = 'Guardado localmente';
          onOk();
        });
    } else {
      // Sin Firebase
      try { localStorage.setItem('nixa_logo', base64); } catch(ex) {}
      onOk();
    }
  } catch(e) {
    if (status) status.textContent = 'Error al leer el archivo';
  }
}

function guardarPreferenciasSistema(btn) {
  var diasVencEl = document.getElementById('cfg-dias-venc');
  var diasAvisoVencPptoEl = document.getElementById('cfg-dias-aviso-venc-ppto');
  var diasVigenciaPreciosEl = document.getElementById('cfg-dias-vigencia-precios');
  var stockMinEl = document.getElementById('cfg-stock-min-def');
  var margenProdEl = document.getElementById('cfg-margen-prod-def');
  var descMaxEl  = document.getElementById('cfg-desc-max-ppto');
  var montoMaxEl = document.getElementById('cfg-monto-max-ppto');
  var monitorEl  = document.getElementById('cfg-mostrar-monitor-recursos');
  var adminSinTimeoutEl = document.getElementById('cfg-admin-sin-timeout');
  var productoVisitaEl = document.getElementById('cfg-producto-visita-tecnica');
  var margenDefaultIngresado = parseFloat((margenProdEl||{}).value);
  if (!isFinite(margenDefaultIngresado) || margenDefaultIngresado < 0) margenDefaultIngresado = 30;
  var datos = {
    diasVencimiento: parseInt((diasVencEl||{}).value) || 15,
    diasAvisoVencimientoPresupuesto: Math.max(0, Math.min(30, parseInt((diasAvisoVencPptoEl||{}).value, 10) || 0)),
    diasVigenciaPrecios: Math.max(1, Math.min(365, parseInt((diasVigenciaPreciosEl||{}).value, 10) || PRECIO_VIGENCIA_DIAS_DEFAULT)),
    stockMinDefault: parseInt((stockMinEl||{}).value) || 5,
    margenProductoDefault: margenDefaultIngresado,
    descuentoLimite: parseFloat((descMaxEl||{}).value) || 10,
    montoLimite: parseFloat((montoMaxEl||{}).value) || 200000,
    mostrarMonitorRecursos: !monitorEl || monitorEl.checked,
    desactivarCierreSesionAdmin: false
      ? !!(adminSinTimeoutEl && adminSinTimeoutEl.checked)
      : window._desactivarCierreSesionAdmin === true,
    productoVisitaTecnicaFbKey: String((productoVisitaEl||{}).value || '')
  };
  if (!window.fbDB) { notify('Sin conexión'); return; }
  var orig = btn.innerHTML;
  btn.innerHTML = '<i class="ti ti-loader-2" style="animation:spin 1s linear infinite"></i> Guardando';
  btn.disabled = true;
  return window.fbUpdate(window.fbRef(window.fbDB,'sisventas/config/preferencias'), datos)
    .then(function(){
      window._diasVencimientoConfig = datos.diasVencimiento;
      window._diasAvisoVencimientoPresupuesto = datos.diasAvisoVencimientoPresupuesto;
      window._diasVigenciaPrecios = datos.diasVigenciaPrecios;
      window._stockMinDefault = datos.stockMinDefault;
      window._margenProductoDefault = datos.margenProductoDefault;
      window._productoVisitaTecnicaFbKey = datos.productoVisitaTecnicaFbKey;
      aplicarVisibilidadMonitorRecursos(datos.mostrarMonitorRecursos);
      window._desactivarCierreSesionAdmin = datos.desactivarCierreSesionAdmin;
      if (typeof resetSessionTimer === 'function' && isAuthenticated) resetSessionTimer();
      if (window.APROBACION_CONFIG) {
        APROBACION_CONFIG.descuentoLimite = datos.descuentoLimite;
        APROBACION_CONFIG.montoLimite = datos.montoLimite;
      }
      btn.innerHTML = '<i class="ti ti-check"></i> Guardado';
      notify('✓ Preferencias guardadas');
    })
    .catch(function(e){
      btn.innerHTML = '<i class="ti ti-alert-circle"></i> Reintentar';
      notify('No se pudieron guardar las preferencias: ' + (e.message || 'Error'));
    })
    .finally(function(){
      setTimeout(function(){ btn.innerHTML=orig; btn.disabled=false; }, 1800);
    });
}

function cargosGuardar() {
  var idExistente = document.getElementById('cargo-id-edit').value;
  var nombre = document.getElementById('cargo-nombre').value.trim();
  if (!nombre) { notify('Ingresá un nombre para el cargo'); return; }

  var soloComision = document.getElementById('cargo-modalidad').value === 'solo_comision';
  var datos = {
    nombre: nombre,
    categoriaBase: document.getElementById('cargo-categoria-base').value.trim(),
    modalidadRemuneracion: soloComision ? 'solo_comision' : 'horas',
    soloComision: soloComision,
    valorHora: soloComision ? 0 : _cargoNumeroEstricto(document.getElementById('cargo-valor-hora').value),
    diasMes: soloComision ? 0 : _cargoNumeroEstricto(document.getElementById('cargo-dias-mes').value),
    valorHoraExtra: soloComision ? 0 : _cargoNumeroEstricto(document.getElementById('cargo-valor-hora-extra').value)
  };

  var id = idExistente || nombre.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');
  if (!idExistente && CARGOS_DATA[id]) { notify('Ya existe un cargo con ese nombre'); return; }

  if (!window.fbDB) { notify('Sin conexión'); return; }
  var promesaGuardar = _cargoGuardarSeguro(id, datos, idExistente ? window._cargoModalBase : null, !idExistente);
  return promesaGuardar
    .then(function(){
      notify('✓ Cargo guardado');
      document.getElementById('modal-cargo').style.display = 'none';
    })
    .catch(function(e){ notify('Error: '+e.message); });
}

