function confirmarPagoGasto() {
  if (window._pagoGastoGuardadoEnCurso) { notify('Ya se está registrando este pago'); return; }
  if (!puedeAdministrarGastos()) { notify('Solo administración puede registrar pagos de gastos'); return; }
  var medio = document.getElementById('mpg-medio').value;
  var montoNuevo = getMontoRaw(document.getElementById('mpg-monto'));
  if (!montoNuevo || montoNuevo <= 0) { notify('Ingresá un monto válido'); return; }

  var keys = (_gastoPagoMultipleKeys && _gastoPagoMultipleKeys.length) ? _gastoPagoMultipleKeys.slice() : (_gastoFbKeyPago ? [_gastoFbKeyPago] : []);
  if (!keys.length) return;

  var loteKey = keys.length > 1 ? ('lote_' + Date.now()) : null;
  var restanteAPagar = montoNuevo;
  var cargas = [];

  keys.forEach(function(k){
    var g = (gastosData||[]).find(function(x){ return x.fbKey===k; });
    if (!g) return;
    var resta = restoGasto(g);
    var pagoEste = keys.length > 1 ? Math.min(resta, restanteAPagar) : Math.min(resta, montoNuevo);
    restanteAPagar -= pagoEste;
    if (pagoEste > 0) cargas.push({fbKey:k,monto:pagoEste});
  });

  if (!cargas.length) { notify('No hay saldo pendiente para pagar'); return; }
  if (restanteAPagar > 0.01) { notify('El importe supera el saldo pendiente de los gastos seleccionados'); return; }
  window._pagoGastoGuardadoEnCurso = true;
  _pagoGastoBotonGuardar(true);
  return _registrarPagosGastosAtomico(cargas,medio,_pagoGastoComprobante,loteKey).then(function(){
    if (typeof registrarActividad === 'function') {
      registrarActividad(keys.length > 1 ? 'Pago múltiple de gastos' : 'Pago de gasto', keys.length + ' gasto(s) · $' + Math.round(montoNuevo).toLocaleString('es-AR') + ' · ' + medio);
    }
    notify(keys.length > 1 ? '✓ Pago múltiple registrado' : '✓ Pago registrado');
    document.getElementById('modal-pago-gasto').style.display = 'none';
    _gastoFbKeyPago = null;
    _gastoPagoMultipleKeys = [];
    _pagoGastoComprobante = null;
    cancelarPagoMultipleGastos();
  }).catch(function(e){ notify('Error al registrar pago: ' + e.message); })
    .finally(function(){ window._pagoGastoGuardadoEnCurso = false; _pagoGastoBotonGuardar(false); });
}

function asistGenerarPresupuesto() {
  var cliInp = document.getElementById('asist-cli-inp');
  var cli    = cliInp.value.trim();
  var clienteAsistenteKey = String(cliInp.dataset.clienteKey || '').trim();
  var clienteAsistente = clienteAsistenteKey
    ? (clientesData||[]).find(function(c){ return String(c.fbKey || c.id || '') === clienteAsistenteKey; })
    : null;
  if (!clienteAsistente) { notify('Seleccioná el cliente desde la lista antes de generar el presupuesto'); return; }
  var obs    = document.getElementById('asist-obs').value.trim();
  var prods  = asistProductosSel.filter(function(p){ return p.qty>0; });
  if (!prods.length) { notify('No hay productos en el sistema'); return; }

  var itemSinPrecio = prods.find(function(p){ return !p.precio || p.precio <= 0; });
  if (itemSinPrecio) { notify('No se puede generar el presupuesto: "'+itemSinPrecio.nombre+'" no tiene precio cargado'); return; }

  var total  = prods.reduce(function(s,p){ return s+p.precio*p.qty; },0);
  var cfg    = ASIST_RUBROS[asistState.rubro];

  var ppto = {
    id:          '',
    numero:      '',
    cliente:     clienteAsistente.nombre || cli,
    clienteFbKey: clienteAsistente.fbKey || clienteAsistente.id || '',
    clienteKey:   clienteAsistente.fbKey || clienteAsistente.id || '',
    clienteId:    clienteAsistente.id || clienteAsistente.fbKey || '',
    fecha:       svFechaLocalISO(),
    estado:      'borrador',
    observaciones: obs || ('Generado por asistente: '+cfg.nombre),
    items:       prods.map(function(p){ return { descripcion:p.nombre, qty:p.qty, precio:p.precio, sub:p.precio*p.qty }; }),
    subtotal:    total,
    conIva:      false,
    total:       total,
    ts:          Date.now(),
    usuario:     currentUser||''
  };

  if (!window.fbDB) { notify('Sin conexión'); return; }
  return reservarSiguientePptoId()
    .then(function(numPpto) {
      ppto.id = numPpto;
      ppto.numero = numPpto;
      return pptoPersistirGuardar(ppto).then(function(){ return numPpto; });
    })
    .then(function(numPpto) {
      notify('✓ Presupuesto '+numPpto+' creado — $'+total.toLocaleString('es-AR'));
      // Volver al inicio del asistente
      setTimeout(function() {
        document.getElementById('asist-resumen').style.display  = 'none';
        document.getElementById('asist-inicio').style.display   = '';
        // Ir a ver el presupuesto
        showPage('presupuesto', document.querySelector('[onclick*=presupuesto]'));
      }, 1000);
    })
    .catch(function(e){ notify('Error: '+e.message); });
}

function guardarMovEmp() {
  if (window._movEmpGuardando) { notify('El movimiento ya se está guardando'); return; }
  if (!ctaEmpActual || !window.fbDB) { notify('Sin conexión o empleado no seleccionado'); return; }
  var montoInput = document.getElementById('movi-monto');
  var monto = getMontoRaw(montoInput);
  // El campo monetario conserva el valor numérico en dataset.raw, pero puede
  // no inicializarse en modales abiertos después de la carga o tras autocompletar.
  // En ese caso se acepta el valor visible con formato argentino.
  if (!monto && montoInput) {
    monto = parseFloat(String(montoInput.value || '').replace(/\./g, '').replace(',', '.').replace(/[^0-9.-]/g, '')) || 0;
  }
  if (window._movEmpFotoLeyendo) { notify('Esperá un instante: se está preparando la foto del comprobante'); return; }
  if (!monto) { notify('Ingresá un monto'); return; }
  var empActual = Object.values(empData||{}).find(function(e){ return e.fbKey === ctaEmpActual; });
  var esAdmin = window.tienePermiso('empleados.crearMovimientoAprobado');
  var esGestorAdelanto = _puedeGestionarAdelantos();
  var soloAdelanto = document.getElementById('modal-movi-emp') && document.getElementById('modal-movi-emp').dataset.modo === 'adelanto-directo';
  var tipoElegido = soloAdelanto ? 'adelanto' : document.getElementById('movi-tipo').value;
  if (['sueldo','hextra','comision'].includes(tipoElegido)) {
    notify('Ese concepto se registra únicamente desde su circuito específico');
    return;
  }
  if (!esAdmin && !['adelanto','transporte','materiales','otro'].includes(tipoElegido)) {
    notify('Ese tipo de movimiento solamente puede cargarlo el administrador');
    return;
  }
  var estadoElegido = esAdmin ? document.getElementById('movi-estado').value : 'pendiente';
  // La procedencia define el circuito: carga directa del Admin = entrega;
  // carga del empleado = solicitud pendiente.
  if (esGestorAdelanto && tipoElegido === 'adelanto') estadoElegido = 'pagado';
  var medioElegido = estadoElegido === 'pagado' ? String((document.getElementById('movi-medio')||{}).value||'').trim() : '';
  if (esGestorAdelanto && estadoElegido === 'pagado' && !medioElegido) {
    notify('Seleccioná el medio de pago');
    return;
  }
  var nuevo = {
    tipo:        tipoElegido,
    fecha:       document.getElementById('movi-fecha').value,
    descripcion: document.getElementById('movi-desc').value.trim(),
    monto:       monto,
    estado:      estadoElegido,
    usuario:     currentUser || 'admin',
    empleadoNombre: empActual ? (empActual.nombre || '') : '',
    empleadoId:  ctaEmpActual,
    origenCarga: esGestorAdelanto ? 'gestion' : 'solicitud_empleado',
    creadoPorRol: currentRole || (esGestorAdelanto ? 'gestor' : 'empleado'),
    ts:          Date.now(),
    fotoUrl:     movEmpFotoBase64 || null,
    fotoBase64:  movEmpFotoBase64 || null
  };
  if(tipoElegido==='adelanto'){
    nuevo.periodoDescuento=String((document.getElementById('movi-periodo-descuento')||{}).value||'');
    if(!/^[1-9]\d{3}-(0[1-9]|1[0-2])$/.test(nuevo.periodoDescuento)){notify('Elegí el mes de descuento del adelanto');return;}
  }
  if (esGestorAdelanto && nuevo.estado === 'pagado') {
    nuevo.medioPago = medioElegido;
    nuevo.montoPagado = monto;
    nuevo.fechaPago = nuevo.fecha;
    nuevo.pagos = {};
    nuevo.pagos['pago_' + Date.now()] = {
      fecha: nuevo.fecha,
      monto: monto,
      medio: medioElegido,
      concepto: tipoElegido,
      usuario: currentUser || 'admin',
      rol: currentRole || 'admin',
      ts: Date.now()
    };
  }
  var esPeriodico = !soloAdelanto && esAdmin && document.getElementById('movi-periodico') && document.getElementById('movi-periodico').checked;
  var reglaPeriodica = null;
  if (esPeriodico) {
    var dia = parseInt(document.getElementById('movi-periodico-dia').value) || 1;
    nuevo.periodico = true;
    nuevo.periodicoDia = dia;
    reglaPeriodica = {key:window.fbPush(window.fbRef(window.fbDB, 'sisventas/gastos_periodicos_emp/' + ctaEmpActual)).key,data:{
      tipo: nuevo.tipo,
      descripcion: nuevo.descripcion,
      monto: monto,
      dia: dia,
      activo: true,
      empleadoId: ctaEmpActual,
      empleadoNombre: nuevo.empleadoNombre,
      creadoPor: currentUser || 'admin',
      ts: Date.now()
    }};
  }
  window._movEmpGuardando = true;
  _movEmpBotonGuardar(true, 'Guardando...');
  return _guardarMovimientoEmpleado(nuevo, nuevo.fotoUrl ? 'Movimiento guardado con comprobante' : 'Movimiento guardado', reglaPeriodica)
    .catch(function(e){ notify('Error al guardar el movimiento: ' + e.message); })
    .finally(function(){ window._movEmpGuardando = false; _movEmpBotonGuardar(false); });
}

function registrarMovCaja() {
  if (window._cajaGuardando) { notify('Ya se está registrando este movimiento'); return; }
  if (!window.fbDB) { notify('Sin conexión'); return; }
  var tipo = document.getElementById('cm-tipo').value;
  var monto = getMontoRaw(document.getElementById('cm-monto'));
  var concepto = document.getElementById('cm-concepto').value.trim();
  var medio = document.getElementById('cm-medio').value;

  if (!monto) { notify('Ingresá el monto'); return; }
  if (!concepto) { notify('Ingresá el concepto'); return; }

  var hoy = svFechaLocalISO();
  var usuarioKey = (currentUser||'sinusuario').replace(/[.\#\$\[\]\/]/g,'_');
  // Mismo criterio de scope que fbCargarCaja: admin/administrativo a la caja
  // consolidada bajo su propia clave de usuario (se suma con los demás al leer);
  // vendedor/técnico siempre a su propia sub-rama.
  var mov = { tipo:tipo, monto:monto, concepto:concepto, medio:medio, usuario:currentUser||'', ts:Date.now(), hora:new Date().toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'}) };
  var operacionKey = _claveOperacionConcurrente('movcaja', [hoy, usuarioKey, tipo, monto, concepto, medio]);
  window._cajaGuardando = true;
  return _registrarMovimientoCajaAtomico(hoy, usuarioKey, operacionKey, mov)
    .then(function() {
      notify('✓ Movimiento de caja registrado');
      _hide('caja-mov-form');
      _setMontoInput(document.getElementById('cm-monto'), 0);
      document.getElementById('cm-concepto').value = '';
      fbCargarCaja();
    }).catch(function(e){ notify('Error: '+e.message); })
    .finally(function(){ window._cajaGuardando = false; });
}

function guardarGastoRapido() {
  var monto = getMontoRaw(document.getElementById('gr-monto'));
  var desc  = document.getElementById('gr-descripcion').value.trim();
  if (!desc)  { notify('Ingresá una descripción'); return; }
  if (!monto) { notify('Ingresá el monto'); return; }
  if (!window.fbDB) { notify('Sin conexión'); return; }

  var pagueYo = document.getElementById('gr-pagado-yo').checked;
  var miEmpleado = null;
  if (pagueYo) {
    miEmpleado = svEmpleadoPropio();
  }

  var ahora = Date.now();
  var fechaGasto = document.getElementById('gr-fecha').value;
  var medioGasto = document.getElementById('gr-medio').value;
  var datos = {
    fecha:          fechaGasto,
    vencimiento:    '',
    tipo:           'Variable',
    categoria:      document.getElementById('gr-categoria').value,
    descripcion:    desc,
    monto:          monto,
    montoPagado:    pagueYo ? 0 : monto,  // si lo pagó un técnico, queda pendiente hasta reembolso
    estado:         pagueYo ? 'pendiente' : 'pagado',
    medio:          medioGasto,
    proveedor:      '',
    comprobante:    '',
    empleadoId:     miEmpleado ? miEmpleado.fbKey : null,
    empleadoNombre: miEmpleado ? miEmpleado.nombre : null,
    reembolsado:    false,
    esFijoBase:     false,
    fotoBase64:     gastoRapidoFotoBase64 || null,
    usuario:        currentUser || '',
    ts:             ahora
  };
  // Un gasto abonado debe tener el mismo comprobante contable que el alta
  // completa. Tesoreria se alimenta de pagos, no solo del estado del gasto.
  if (!pagueYo) {
    datos.pagos = {};
    datos.pagos['pago_inicial_' + ahora] = {
      fecha: fechaGasto,
      monto: monto,
      medio: medioGasto,
      usuario: currentUser || '',
      ts: ahora,
      origen: 'gasto_rapido'
    };
  }

  return _crearGastoSinDuplicar(datos)
    .then(function() {
      if (miEmpleado) {
        notify('✓ Gasto cargado · $'+monto.toLocaleString('es-AR')+' visible en tu cuenta corriente');
      } else {
        notify('✓ Gasto cargado correctamente');
      }
      cerrarGastoRapido();
    })
    .catch(function(e){ notify('Error: '+e.message); });
}

function chatAbrirDirectos(silencioso) {
  chatAudioCancelar();
  document.getElementById('chat-online-banner')?.remove();
  var cargaId = ++_chatCargaId;
  _chatListaVisible = [];
  chatCancelReply();
  chatCerrarAdjuntos();
  if (_chatListener) { _chatListener(); _chatListener = null; }
  var buscador = document.getElementById('chat-buscar');
  if (buscador) { buscador.value = ''; buscador.disabled = true; }
  _chatCanal = 'directos';
  chatEscucharEscribiendo('directos');
  var btnLimpiar = document.getElementById('btn-chat-admin-limpiar');
  if (btnLimpiar) btnLimpiar.style.display = 'none';
  chatMarcarCanalActivo('directos');
  var msgs = document.getElementById('chat-messages');
  if (!msgs) return;
  if (!silencioso) msgs.innerHTML = '<div style="text-align:center;color:var(--text3);padding:24px;font-size:13px">Cargando conversaciones...</div>';

  if (!window.fbDB) return;

  return window.chatDirectosSnapshot().then(function(snap) {
    if (cargaId !== _chatCargaId) return;
    var data = snap.val() || {};
    var miKey = currentUserUid;
    var conversaciones = [];

    Object.keys(data).forEach(function(canal) {
      if (!canal.startsWith('directo_')) return;
      if (!chatPuedeAccederCanal(canal)) return;
      // Extraer el otro usuario del nombre del canal
      var partes = canal.replace('directo_','').split('_'+miKey).join('_').split(miKey+'_').join('_');
      var mensajes = Object.values(data[canal] || {});
      if (!mensajes.length) return;
      var ultimo = mensajes.sort(function(a,b){ return (b.ts||0)-(a.ts||0); })[0];
      var noLeidos = mensajes.filter(function(m){
        return m.autor !== chatNombreSesion() && !_chatFueLeido(m, chatNombreSesion());
      }).length;
      var otroAutor = mensajes.find(function(m){ return m.autor !== currentUser; });
      var otroUid = Object.keys(window._chatDirectorio || {}).find(function(uid) {
        return uid !== miKey && window.chatDirectoId(uid) === canal;
      });
      var persona = otroUid && window._chatDirectorio[otroUid];
      var otroNombre = (persona && persona.nombre) || (otroAutor && otroAutor.autor) || 'Usuario no disponible';
      conversaciones.push({ canal, otroUid, otroNombre, ultimo, noLeidos });
    });

    // Presencia indica disponibilidad; no crea conversaciones sin mensajes.

    if (!conversaciones.length) {
      msgs.innerHTML = '<div style="text-align:center;color:var(--text3);padding:24px;font-size:13px">No hay conversaciones directas aún</div>';
      window.SVChatContacts?.decorate(msgs, conversaciones);
      return;
    }

    // Ordenar: con mensajes no leídos primero, luego por último mensaje
    conversaciones.sort(function(a,b){
      if (b.noLeidos !== a.noLeidos) return b.noLeidos - a.noLeidos;
      return ((b.ultimo && b.ultimo.ts)||0) - ((a.ultimo && a.ultimo.ts)||0);
    });

    msgs.innerHTML = '<div style="padding:8px 0">' +
      '<div style="font-size:11px;color:var(--text3);margin-bottom:8px;padding:0 4px">MENSAJES DIRECTOS</div>' +
      conversaciones.map(function(c) {
        var presencia = buscarPresenciaPorNombre(c.otroNombre);
        var online    = presenciaEstaActiva(presencia);
        var dotColor  = online ? 'var(--green)' : 'var(--text3)';
        var ultimoTxt = c.ultimo ? (c.ultimo.texto || (c.ultimo.audioUrl ? '🎤 Audio' : c.ultimo.fotoUrl ? '📷 Foto' : (c.ultimo.archivoUrl ? '📎 ' + (c.ultimo.archivoNombre || 'Archivo') : ''))) : 'Nueva conversación';
        var badge     = c.noLeidos > 0
          ? '<span style="background:var(--red);color:#fff;border-radius:99px;font-size:10px;padding:1px 6px;font-weight:600">'+c.noLeidos+'</span>'
          : '';
        return '<div style="display:flex;align-items:center;gap:10px;padding:10px 4px;cursor:pointer;border-bottom:0.5px solid var(--border)" onclick="chatAbrirDirecto(\''+escapeHTML(c.otroNombre)+'\')">' +
          '<div style="position:relative;flex-shrink:0">' +
            '<div style="width:36px;height:36px;border-radius:50%;background:var(--bg3);display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:600">'+escapeHTML((c.otroNombre||'?')[0].toUpperCase())+'</div>' +
            '<span style="position:absolute;bottom:0;right:0;width:10px;height:10px;border-radius:50%;background:'+dotColor+';border:2px solid var(--bg2)"></span>' +
          '</div>' +
          '<div style="flex:1;min-width:0">' +
            '<div style="font-size:13px;font-weight:500">'+escapeHTML(c.otroNombre||'')+'</div>' +
            '<div style="font-size:11px;color:var(--text3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escapeHTML(ultimoTxt.slice(0,40))+'</div>' +
          '</div>' +
          badge +
          '<i class="ti ti-chevron-right" style="color:var(--text3);flex-shrink:0"></i>' +
        '</div>';
      }).join('') +
    '</div>';
    window.SVChatContacts?.decorate(msgs, conversaciones);
  }).catch(function() {
    if (cargaId !== _chatCargaId) return;
    msgs.innerHTML = '<div style="text-align:center;color:var(--text3);padding:24px">Error cargando conversaciones</div>';
  });
}

function otCargarCredenciales(ot) {
  var box  = document.getElementById('ot-cred-box');
  var lista = document.getElementById('ot-cred-lista');
  if (!box || !lista) return;

  // Limpiar antes de iniciar la consulta. La secuencia impide que una respuesta
  // lenta de la OT anterior vuelva a pintar sus credenciales en la OT actual.
  var secuencia = ++_otCredencialesCargaSecuencia;
  _otCredencialesClienteActual = null;
  _otCredencialesOTActual = ot || null;
  lista.innerHTML = '';
  box.style.display = 'none';
  otCredencialBasicaCerrar();
  var agregarBtn = document.getElementById('ot-cred-agregar-btn');
  if (agregarBtn) agregarBtn.style.display = 'none';

  var cli = _svResolverClienteRegistro(ot, true);
  if (!cli || !window.fbDB) return;
  _otCredencialesClienteActual = cli;
  var puedeEditar = otPuedeEditarCredenciales();
  var clienteCredKey = String(cli.fbKey || cli.id || '');
  if (!clienteCredKey) return;
  if (agregarBtn) agregarBtn.style.display = puedeEditar ? '' : 'none';
  if (puedeEditar) {
    box.style.display = '';
    lista.innerHTML = '<div style="padding:14px;text-align:center;color:var(--text3);font-size:12px">Cargando credenciales...</div>';
  }

  return window.fbGet(window.fbRef(window.fbDB, 'sisventas/credencialesPorCliente/' + clienteCredKey)).then(function(snap) {
    var data = snap.val();
    if (!data && cli.id) {
      return window.fbGet(window.fbRef(window.fbDB, 'sisventas/credenciales/'+cli.id)).then(function(legacySnap){ return legacySnap.val(); });
    }
    return data;
  }).then(function(data) {
    if (secuencia !== _otCredencialesCargaSecuencia) return;
    if (!data) {
      if (puedeEditar) {
        box.style.display = '';
        lista.innerHTML = '<div style="padding:14px;text-align:center;color:var(--text3);font-size:12px">Este cliente todavía no tiene credenciales. Tocá Agregar para cargar la primera.</div>';
      } else {
        lista.innerHTML = '';
        box.style.display = 'none';
      }
      return;
    }
    box.style.display = '';
    var items = Object.values(data);
    lista.innerHTML = items.map(function(c) {
      var ico = (CRED_TIPO_ICONOS||{})[c.tipo] || 'ti-key';
      return '<div style="background:var(--bg3);border-radius:var(--radius);padding:12px;display:flex;gap:12px;align-items:flex-start">' +
        '<div style="width:32px;height:32px;border-radius:6px;background:var(--blue-bg);color:var(--blue);display:flex;align-items:center;justify-content:center;flex-shrink:0"><i class="ti '+ico+'" style="font-size:16px"></i></div>' +
        '<div style="flex:1">' +
          '<div style="font-weight:500;font-size:13px">'+escapeHTML(c.desc||c.tipo||'')+'</div>' +
          '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:6px;margin-top:6px">' +
            (c.user ? '<div><span style="font-size:10px;color:var(--text3);display:block">Usuario</span><span style="font-family:monospace;font-size:13px">'+escapeHTML(c.user)+'</span></div>' : '') +
            (c.pass ? '<div><span style="font-size:10px;color:var(--text3);display:block">Contraseña</span>' +
              '<div style="display:flex;align-items:center;gap:6px">' +
                '<span class="ot-cred-pass" style="font-family:monospace;font-size:13px">••••••••</span>' +
                '<button type="button" data-secret="'+escapeHTML(c.pass||'')+'" onclick="var valor=this.previousElementSibling;valor.textContent=valor.textContent===\'••••••••\'?this.dataset.secret:\'••••••••\'" aria-label="Mostrar u ocultar contraseña" style="background:none;border:none;cursor:pointer;color:var(--text3)"><i class="ti ti-eye" style="font-size:13px"></i></button>' +
              '</div></div>' : '') +
            (c.ip ? '<div><span style="font-size:10px;color:var(--text3);display:block">IP / Sistema</span><span style="font-family:monospace;font-size:12px">'+escapeHTML(c.ip)+(c.puerto?':'+escapeHTML(c.puerto):'')+'</span></div>' : '') +
            ((c.serie || c.numeroSerie || c.serial) ? '<div><span style="font-size:10px;color:var(--text3);display:block">Número de serie</span><span style="font-family:monospace;font-size:12px">'+escapeHTML(c.serie || c.numeroSerie || c.serial)+'</span></div>' : '') +
          '</div>' +
          (c.notas ? '<div style="margin-top:6px;font-size:11px;color:var(--text3);font-style:italic">'+escapeHTML(c.notas)+'</div>' : '') +
        '</div>' +
      '</div>';
    }).join('');
  }).catch(function(){
    if (secuencia !== _otCredencialesCargaSecuencia) return;
    box.style.display = '';
    lista.innerHTML = '<div style="padding:14px;text-align:center;color:var(--red);font-size:12px">' +
      '<i class="ti ti-alert-triangle"></i> No se pudieron cargar las credenciales. ' +
      '<button type="button" class="btn btn-sm" onclick="var ot=(otData||[]).find(function(item){return item.fbKey===otActualId||item.id===otActualId;});if(ot)otCargarCredenciales(ot)" style="margin-left:6px">Reintentar</button>' +
    '</div>';
  });
}

function guardarConfigComisionEmpleado(btn) {
  var tr = btn && btn.closest ? btn.closest('tr[data-empleado-id]') : null;
  if (!tr || !window.fbDB) return;
  var key = tr.dataset.empleadoId;
  var input = tr.querySelector('.cfg-comision-empleado-input');
  var texto = String(input && input.value || '').trim();
  var ref = window.fbRef(window.fbDB, 'sisventas/config/comisionesEmpleados/' + key);
  var promesa;
  if (texto === '') {
    delete CONFIG_COMISIONES_EMPLEADOS[key];
    promesa = window.fbSet(ref, null);
  } else {
    var pct = parseFloat(texto);
    var maxGlobal = parseFloat(APROBACION_CONFIG && APROBACION_CONFIG.maxComisionPct) || 0;
    if (!isFinite(pct) || pct < 0) { notify('Ingresá un porcentaje válido'); return; }
    if (maxGlobal > 0 && pct > maxGlobal) { notify('La excepción no puede superar el tope global de ' + maxGlobal + '%'); return; }
    CONFIG_COMISIONES_EMPLEADOS[key] = { pct:pct, actualizadoTs:Date.now(), actualizadoPor:currentUser||'' };
    promesa = window.fbSet(ref, CONFIG_COMISIONES_EMPLEADOS[key]);
  }
  btn.disabled = true;
  return promesa.then(function(){ notify(texto === '' ? '✓ El empleado vuelve a usar el porcentaje general del cargo' : '✓ Excepción individual guardada'); renderComisionesConfig(); })
    .catch(function(error){ notify('Error: ' + error.message); })
    .finally(function(){ btn.disabled = false; });
}

