function chatEnviar() {
  if (!chatPuedeAccederCanal(_chatCanal)) { notify('No tenés acceso a este grupo.'); return; }
  if (_chatAudio) return chatAudioEnviar();
  var inp = document.getElementById('chat-input');
  var texto = inp ? inp.value.trim() : '';
  if (!texto || !window.fbDB) return;
  var comando = texto.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ');
  if (window.tienePermiso('chat.limpiar') && comando === 'limpiar conversacion') {
    inp.value = ''; chatInputCambio(inp); return chatAdminLimpiar();
  }
  if (_chatCanal === 'directos') { notify('Elegí primero a quién enviar el mensaje'); return; }
  var canalEnvio = _chatCanal;
  inp.value=''; inp.style.height='';
  chatInputCambio(inp);
  var msg = { texto: texto, autor: currentUser||'', autorUid:window.fbAuth?.currentUser?.uid||'', rol: currentRole||'', ts: Date.now(), canal: _chatCanal };
  if (_chatReplyMsg) {
    msg.replyFbKey  = _chatReplyMsg.fbKey;
    msg.replyAutor  = _chatReplyMsg.autor;
    msg.replyTexto  = (_chatReplyMsg.texto||'').slice(0,100);
    chatCancelReply();
  }
  return window.SVChatReadModel.send(canalEnvio, msg).catch(function() {
    if (_chatCanal === canalEnvio && !inp.value) inp.value = texto;
    notify('No se pudo enviar el mensaje. Revisá la conexión y reintentá.');
  });
}

