function guardarFilaConfig(btn) {
  var tr = btn && btn.closest ? btn.closest('tr') : null;
  if (!tr) return;
  var inputs = tr.querySelectorAll('input[type=number]');
  var cargoId = tr.dataset.cargoId;
  var vals = Array.from(inputs).map(function(i){ return parseFloat(i.value)||0; });
  if (!cargoId) { notify('Fila sin cargo ID — recargá la solapa de comisiones'); return; }
  var maxGlobal = parseFloat(APROBACION_CONFIG && APROBACION_CONFIG.maxComisionPct) || 0;
  if (maxGlobal > 0 && vals[0] > maxGlobal) { notify('El porcentaje general no puede superar el tope global de ' + maxGlobal + '%'); return; }
  guardarConfigComisionCargo(cargoId, { pct: vals[0]||0, min: 0, max: 0 });
  if (window.fbDB) {
    return window.fbSet(window.fbRef(window.fbDB, 'sisventas/config/comisiones'), _comisionesParaFirebase())
      .then(function(){ notify('✓ Comisión guardada para ' + ((CARGOS_DATA[cargoId]||{}).nombre || cargoId)); })
      .catch(function(e){ notify('Error: '+e.message); });
  } else {
    notify('Sin conexión a Firebase');
  }
}

function guardarNuevoGenerico() {
  var _svPromesaAccion;
  var tipo = window._modalTipo;
  var cfg  = FORMS_CFG[tipo];
  if (!cfg) { notify('Tipo no configurado'); return; }

  // Recopilar todos los campos del modal
  var obj = { fbKey: null };
  cfg.fields.forEach(function(f) {
    var el = document.getElementById(f.id);
    if (el) obj[f.id.replace(/^n[a-z]+-/, '')] = el.value.trim();
  });

  if (tipo === 'cliente') {
    var cliExistente = window._editingClienteId
      ? (clientesData||[]).find(function(c){ return String(c.id || '') === String(window._editingClienteId) || String(c.fbKey || '') === String(window._editingClienteId); })
      : null;

    var telefonoCliente = obj.tel || '';
    var emailCliente = obj.em || '';
    var direccionCliente = String(obj.dir || '').trim().toLocaleUpperCase('es-AR');
    var nombreIngresado = (String(obj.nm || '').trim().toLocaleUpperCase('es-AR')) + (obj.ap ? ' ' + String(obj.ap).trim().toLocaleUpperCase('es-AR') : '');
    var nuevo = Object.assign({}, cliExistente || {}, {
      id:        cliExistente ? cliExistente.id : String(Date.now()).slice(-6),
      nombre:    nombreIngresado.trim() || '',
      apellidos: String(obj.ap || '').trim().toLocaleUpperCase('es-AR'),
      dni:       obj.dni || '',
      telefono:  telefonoCliente,
      tel:       telefonoCliente,
      mail:      emailCliente,
      email:     emailCliente,
      cuit:      obj.cuit || '',
      razonSocial: String(obj['razon-social'] || '').trim().toLocaleUpperCase('es-AR'),
      empresa:   obj.empresa || '',
      sedeCategoria: String(obj.sede || '').trim(),
      dir:       direccionCliente,
      direccion: direccionCliente,
      localidad: (cliExistente && cliExistente.localidad) || 'Mar del Plata',
      activo:    cliExistente ? cliExistente.activo !== false : true
    });
    var consultaArca = window._clienteArcaConsulta;
    if (consultaArca && String(consultaArca.cuit || '') === String(nuevo.cuit || '').replace(/\D/g,'')) {
      nuevo.condicionImpositiva = consultaArca.condicionImpositiva || nuevo.condicionImpositiva || '';
      nuevo.localidad = consultaArca.localidad || nuevo.localidad || '';
      nuevo.provinciaFiscal = consultaArca.provincia || nuevo.provinciaFiscal || '';
      nuevo.codigoPostalFiscal = consultaArca.codigoPostal || nuevo.codigoPostalFiscal || '';
      nuevo.estadoCuit = consultaArca.estado || nuevo.estadoCuit || '';
      nuevo.actividadesArca = consultaArca.actividades || nuevo.actividadesArca || [];
      nuevo.apocExiste = consultaArca.apocExiste || '';
      nuevo.apocInfo = consultaArca.apocInfo || '';
      nuevo.datosFiscalesFuente = consultaArca.fuente;
      nuevo.datosFiscalesConsultadosEn = consultaArca.consultadoEn;
    }
    if (cliExistente && cliExistente.fbKey) {
      nuevo.fbKey = cliExistente.fbKey;
    }
    if (!cliExistente && _clienteEstructuraDestinoKey) nuevo._clienteEstructuraDestinoKey = _clienteEstructuraDestinoKey;

    if (!nuevo.nombre.trim() && !nuevo.razonSocial) {
      notify('Ingresá al menos nombre o razón social del cliente');
      return;
    }

    return guardarClienteDesdeModal(nuevo);

  } else if (tipo === 'producto') {
    var pv  = parseFloat(obj.pv  || 0);
    var pc  = parseFloat(obj.pc  || 0);
    var pid = String(Date.now()).slice(-5);
    var nuevo = {
      id:          pid,
      codigo:      obj.cod || ('P-' + pid),
      nombre:      obj.desc || '',
      descripcion: obj.desc || '',
      marca:       obj.marca || '',
      moneda:      obj.moneda || 'ARS',
      venta:       pv,
      compra:      pc,
      margen:      pv > 0 ? Math.round((pv-pc)/pv*100*10)/10 : 0,
      stock:       parseInt(obj.stock || 0),
      stockMin:    2,
      activo:      true
    };
    if (typeof fbGuardarProducto === 'function') {
      _svPromesaAccion = fbGuardarProducto(nuevo);
    }
    if (typeof registrarActividad === 'function') {
      registrarActividad('Producto guardado', nuevo.codigo + ' — ' + nuevo.nombre);
    }

  } else if (tipo === 'empleado') {
    var fbKeyEmp = window._modalFbKey;
    var cargoIdSel = obj['cargo-id'] || '';
    var cargoNombreSel = (cargoIdSel && CARGOS_DATA[cargoIdSel]) ? CARGOS_DATA[cargoIdSel].nombre : '';
    var datosEmp = {
      nombre:    ((obj.nm || '') + ' ' + (obj.ap || '')).trim(),
      cargoId:   cargoIdSel,
      cargo:     cargoNombreSel,
      fechaIngreso: obj['fecha-ingreso'] || '',
      telefono:  obj.tel || '',
      mail:      obj.em || '',
      dni:       obj.dni || '',
      tipoEmpleado:    obj.tipo || 'Empleado',
      activo:    (obj.activo || 'Activo') !== 'Inactivo'
    };
    if (!fbKeyEmp) datosEmp.historial = [{ tipo:'alta', motivo:'Ingreso', fecha: svFechaLocalISO(), usuario: currentUser||'' }];
    if (!datosEmp.nombre.trim()) { notify('Ingresá nombre y apellido'); return; }
    if (window.fbDB) {
      if (fbKeyEmp) {
        _svPromesaAccion = window.fbUpdate(window.fbRef(window.fbDB, 'sisventas/empleados/' + fbKeyEmp), datosEmp)
          .then(function(){
            notify('Empleado actualizado');
            if (typeof registrarActividad === 'function') registrarActividad('Empleado editado', datosEmp.nombre);
          })
          .catch(function(e){ notify('Error: '+e.message); });
      } else {
        var legajos = Object.values(empData||{}).map(function(e){ return parseInt(e.legajo)||0; });
        var maxLeg = legajos.length ? Math.max.apply(null, legajos) : 0;
        datosEmp.legajo = maxLeg + 1;
        datosEmp.ts = Date.now();
        _svPromesaAccion = window.fbPush(window.fbRef(window.fbDB, 'sisventas/empleados'), datosEmp)
          .then(function(){
            notify('Empleado guardado — Legajo N° '+datosEmp.legajo);
            if (typeof registrarActividad === 'function') registrarActividad('Empleado creado', datosEmp.nombre + ' — Legajo N° ' + datosEmp.legajo);
          })
          .catch(function(e){ notify('Error: '+e.message); });
      }
    } else { notify('Sin conexión'); }

  } else if (tipo === 'gasto') {
    var fbKey = window._modalFbKey;
    var datos = {
      fecha:       obj.f || svFechaLocalISO(),
      tipo:        obj.tipo || 'Variable',
      descripcion: obj.desc || '',
      categoria:   obj.cat || '',
      monto:       parseFloat(obj.monto) || 0,
      medio:       obj.medio || 'Efectivo',
      estado:      'Pagado'
    };
    if (window.fbDB) {
      var promesa = fbKey
        ? window.fbUpdate(window.fbRef(window.fbDB, 'sisventas/gastos/' + fbKey), datos)
        : (datos.ts = Date.now(), _crearGastoSinDuplicar(datos));
      _svPromesaAccion = promesa.then(function() { notify(fbKey ? 'Gasto actualizado' : 'Gasto registrado'); })
             .catch(function(e) { notify('Error: ' + e.message); });
    } else { notify('Sin conexión'); }

  } else if (tipo === 'proveedor') {
    var fbKey = window._modalFbKey;
    var indiceAltaProducto = Number.isInteger(window._pfProveedorAltaPendienteIdx)
      ? window._pfProveedorAltaPendienteIdx : null;
    var datos = {
      nombre:    String(obj.nm || '').trim().toLocaleUpperCase('es-AR'),
      rubro:     obj.rub || '',
      telefono:  obj.tel || '',
      mail:      obj.em || '',
      web:       obj.web || '',
      monedaPrecios: String(obj.monedaPrecios || 'ARS').split(' ')[0],
      usuario:   obj.user || '',
      password:  obj.pass || '',
      condPago:  obj.cond || 'Contado',
      contacto:  obj.contacto || '',
      condicionComercial: {activa:obj.regla === 'Aplicar descuento',descuentoPorcentaje:Number(obj.descuento || 0),medioPago:obj.medioPrecio === 'Depósito o transferencia' ? 'transferencia' : obj.medioPrecio === 'Otros medios de pago' ? 'otros' : ''},
      activo:    true
    };
    if (!datos.nombre) { notify('Ingresá el nombre del proveedor'); return; }
    if (!['ARS','USD','PYG'].includes(datos.monedaPrecios)) { notify('Seleccioná una moneda de precios válida'); return; }
    if (!Number.isFinite(datos.condicionComercial.descuentoPorcentaje) || datos.condicionComercial.descuentoPorcentaje < 0 || datos.condicionComercial.descuentoPorcentaje >= 100) { notify('El descuento debe estar entre 0 y menos de 100%'); return; }
    window._pfProveedorAltaPendienteIdx = null;
    var proveedorExistente = !fbKey ? (proveedoresData || []).find(function(prov) {
      return prov && prov.activo !== false && String(prov.nombre || '').trim().toLowerCase() === datos.nombre.toLowerCase();
    }) : null;
    if (proveedorExistente) {
      if (indiceAltaProducto !== null) {
        seleccionarProveedorProducto(indiceAltaProducto, proveedorExistente.fbKey || proveedorExistente.key || proveedorExistente.id || '');
        notify('Ese proveedor ya existía y quedó seleccionado');
      } else {
        notify('Ese proveedor ya está registrado');
      }
      cerrarModalNuevoGenerico();
      return;
    }
    if (window.fbDB) {
      if (!fbKey) datos.ts = Date.now();
      var registroProveedor = Object.assign({}, datos, fbKey ? { fbKey:fbKey } : {});
      _svPromesaAccion = proveedorPersistirGuardar(registroProveedor).then(function(proveedorGuardado) {
        if (window.verificarConexionProveedor && proveedorGuardado && proveedorGuardado.fbKey && datos.web) {
          window.verificarConexionProveedor(proveedorGuardado.fbKey, false);
        }
        if (!fbKey && indiceAltaProducto !== null) {
          var nuevaKey = String((proveedorGuardado && proveedorGuardado.fbKey) || '');
          if (nuevaKey && !(proveedoresData || []).some(function(prov){ return String(prov.fbKey || '') === nuevaKey; })) {
            proveedoresData.push(Object.assign({ fbKey: nuevaKey }, datos));
          }
          var fila = prodProveedoresActuales[indiceAltaProducto];
          if (fila) {
            fila.nombre = datos.nombre;
            fila.proveedorKey = nuevaKey;
            fila.proveedorFbKey = nuevaKey;
            renderTablaProveedoresProducto();
          }
          notify('Proveedor guardado y seleccionado en el producto');
        } else {
          notify(fbKey ? 'Proveedor actualizado' : 'Proveedor guardado');
        }
      })
             .catch(function(e) { notify('Error: ' + e.message); });
    } else { notify('Sin conexión'); }

  } else if (tipo === 'usuario') {
    var fbKeyUsu = window._modalFbKey;
    // Inyectar select de empleado vinculado si no existe
    setTimeout(function() {
      if (!document.getElementById('nu-emp-vinculado')) {
        var cont = document.getElementById('nu-activo');
        if (cont) {
          var wrapper = cont.closest('.fg');
          if (wrapper) {
            var div = document.createElement('div');
            div.className = 'fg full';
            div.style.marginTop = '8px';
            var lbl = document.createElement('label');
            lbl.textContent = 'Empleado vinculado';
            var sel = document.createElement('select');
            sel.id = 'nu-emp-vinculado';
            var opts = '<option value="">— Sin vincular —</option>';
            Object.values(empData||{}).filter(function(e){ return e.activo !== false; })
              .sort(function(a,b){ return (a.nombre||'').localeCompare(b.nombre||''); })
              .forEach(function(e){ opts += '<option value="'+e.fbKey+'">'+escapeHTML(e.nombre)+'</option>'; });
            sel.innerHTML = opts;
            if (fbKeyUsu && window.usuariosData) {
              var uActual = (window.usuariosData||[]).find(function(u){ return u.fbKey === fbKeyUsu; });
              if (uActual && uActual.empleadoFbKey) sel.value = uActual.empleadoFbKey;
            }
            div.appendChild(lbl);
            div.appendChild(sel);
            var form = wrapper.parentElement;
            if (form) form.appendChild(div);
          }
        }
      }
    }, 100);
    var rolRaw   = (obj.rol||'').trim();
    var rolMap   = {
      'Administrador':'admin','administrador':'admin',
      'Administrativo':'administrativo','administrativo':'administrativo',
      'Vendedor':'vendedor','vendedor':'vendedor',
      'Técnico-vendedor':'tecnico_vendedor','Tecnico-vendedor':'tecnico_vendedor','tecnico-vendedor':'tecnico_vendedor','tecnico_vendedor':'tecnico_vendedor',
      'Compras Paraguay':'compras_paraguay','compras_paraguay':'compras_paraguay',
      'Distribuidora':'distribuidora','distribuidora':'distribuidora',
      'Técnico':'tecnico','Tecnico':'tecnico','técnico':'tecnico','tecnico':'tecnico'
    };
    var rolFinal = rolMap[rolRaw] || rolRaw.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'') || 'administrativo';
    var login    = (obj.user||'').replace('@sistemanixa.com','').replace(/\s/g,'').toLowerCase();
    var email    = login + '@sistemanixa.com';
    var pass     = (obj.pass||'').trim();
    var empVinculado = (document.getElementById('nu-emp-vinculado')||{}).value || '';
    var datosUsu = {
      nombre:       obj.nm || '',
      login:        login,
      mail:         email,
      rol:          rolFinal,
      activo:       (obj.activo||'Activo') !== 'Inactivo',
      empleadoFbKey: empVinculado || '',
      ts:           Date.now()
    };
    // Passwords belong to Firebase Auth only; never store a readable profile copy.
    if (!datosUsu.nombre) { notify('Ingresá el nombre completo'); return; }
    if (!login)           { notify('Ingresá el nombre de usuario'); return; }

    if (fbKeyUsu) {
      if(pass) { notify('Para cambiar el acceso usá Gestionar acceso en Usuarios'); return; }
      _svPromesaAccion = window.guardarUsuarioConAccesoChat(datosUsu,fbKeyUsu)
        .then(function(){ notify('✓ Usuario actualizado'); })
        .catch(function(e){ notify('Error: '+e.message); });

    } else {
      if (!pass) { notify('Ingresá una contraseña inicial para el usuario'); return; }
      if (pass.length < 6) { notify('La contraseña debe tener al menos 6 caracteres'); return; }

      var adminEmail = window.fbAuth.currentUser ? window.fbAuth.currentUser.email : null;
      var adminPass  = null; // no podemos recuperarla, usamos re-autenticación

      notify('Creando usuario en Firebase Auth...');

      _svPromesaAccion = window.fbCreateUserManaged(email, pass)
        .then(function(cred) {
          var nuevoUid = cred.user.uid;
          datosUsu.uid = nuevoUid;
          return window.guardarUsuarioConAccesoChat(datosUsu);
        })
        .then(function() {
          notify('✓ Usuario ' + email + ' creado correctamente');

        })
        .catch(function(e) {
          var msg = e.code === 'auth/email-already-in-use'
            ? 'Ese email ya existe en Firebase Auth. El usuario puede usar "Olvidé mi contraseña" para acceder.'
            : e.code === 'auth/weak-password'
            ? 'La contraseña es muy débil. Usá al menos 6 caracteres.'
            : 'Error al crear usuario: ' + (e.message||e.code);
          notify(msg);
        });
    }

  } else if (tipo === 'garantia') {
    var clienteGarantia = document.getElementById('ng2-cli');
    var ventaGarantia = document.getElementById('ng2-venta');
    var equipoGarantia = document.getElementById('ng2-eq');
    if (!clienteGarantia || !clienteGarantia.dataset.clienteKey) { notify('Seleccioná un cliente válido de la lista'); return; }
    if (!ventaGarantia || !ventaGarantia.value) { notify('Seleccioná una venta del cliente'); return; }
    if (!equipoGarantia || !equipoGarantia.value) { notify('Seleccioná un equipo incluido en la venta'); return; }
    var venc = new Date(obj.inst||Date.now());
    venc.setMonth(venc.getMonth() + parseInt(obj.meses||12));
    _svPromesaAccion = guardarGarantia({ equipo:obj.eq, equipoCodigo:(equipoGarantia.selectedOptions[0] && equipoGarantia.selectedOptions[0].dataset.codigo) || '', productoFbKey:(equipoGarantia.selectedOptions[0] && equipoGarantia.selectedOptions[0].dataset.productoKey) || '', serie:obj.serie, cliente:obj.cli, clienteFbKey:clienteGarantia.dataset.clienteKey, fechaInst:obj.inst, meses:obj.meses, fechaVenc:venc.toISOString().split('T')[0], venta:obj.venta, ventaFbKey:(ventaGarantia.selectedOptions[0] && ventaGarantia.selectedOptions[0].dataset.fbKey) || '' });

  } else if (tipo === 'remito') {
    return guardarRemitoDesdeModal({ numero:obj.num, cliente:obj.cli, fecha:obj.fecha||svFechaLocalISO(), venta:obj.venta, descripcion:obj.desc, estado:'pendiente' });

  } else if (tipo === 'servicio') {
    var numSv = obj.num || ('SV-' + String((window._servData||[]).length + 1).padStart(4,'0'));
    return guardarRegistroSimpleDesdeModal(tipo, { numero:numSv, cliente:obj.cli, descripcion:obj.desc, tecnico:obj.tec||'Sin asignar', fecha:obj.fecha||svFechaLocalISO(), garantia:obj.garantia||'—', estado:obj.estado||'En curso' }, JSON.stringify(obj));

  } else if (tipo === 'evento') {
    return guardarRegistroSimpleDesdeModal(tipo, { fecha:obj.f, hora:obj.h, descripcion:obj.desc, cliente:obj.cli, empleado:obj.emp, tipo:obj.tipo, estado:'pendiente' }, JSON.stringify(obj));

  } else if (tipo === 'ticket') {
    var numTkt = obj.num || ('TK-' + String((window.usuariosData||[]).length + Date.now()).slice(-4));
    return guardarRegistroSimpleDesdeModal(tipo, { numero:numTkt, cliente:obj.cli, equipo:obj.eq, descripcion:obj.desc, prioridad:obj.p, estado:obj.est||'Abierto', tecnico:obj.tec||'Sin asignar' }, JSON.stringify(obj));

  } else if (tipo === 'ordencompra') {
    // Compatibilidad para cualquier botón antiguo que todavía intente abrir el
    // formulario genérico: se lo deriva al único editor vigente.
    cerrarModalNuevoGenerico();
    if (typeof window.abrirNuevaOrden === 'function') window.abrirNuevaOrden();
    return;

  } else {
    notify('Registro guardado');
  }

  cerrarModalNuevoGenerico();
  return _svPromesaAccion;
}

function guardarGarantia(datos) {
  if (!window.fbDB) return;
  return window.fbPush(window.fbRef(window.fbDB, 'sisventas/garantias'), Object.assign(datos||{}, { ts: Date.now(), usuario: currentUser }))
    .then(function(){ notify('Garantía registrada'); });
}
